@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PawSyncApp() {
 val navController = rememberNavController()

 Scaffold(
 bottomBar = {
 NavigationBar {
 val navBackStackEntry by navController.currentBackStackEntryAsState()
 val currentRoute = navBackStackEntry?.destination?.route

 NavigationBarItem(
 icon = { Icon(Icons.Default.Home, contentDescription = "Dashboard") },
 label = { Text("Home") },
 selected = currentRoute == "dashboard",
 onClick = {
 navController.navigate("dashboard") {
 popUpTo("dashboard") { inclusive = true }
 }
 }
 )
 NavigationBarItem(
 icon = { Icon(Icons.Default.MonitorHeart, contentDescription = "Health") },
 label = { Text("Health") },
 selected = currentRoute == "health",
 onClick = {
 navController.navigate("health") {
 popUpTo("dashboard")
 }
 }
 )
 NavigationBarItem(
 icon = { Icon(Icons.Default.Chat, contentDescription = "AI Chat") },
 label = { Text("AI Chat") },
 selected = currentRoute == "aichat",
 onClick = {
 navController.navigate("aichat") {
 popUpTo("dashboard")
 }
 }
 )
 NavigationBarItem(
 icon = {
 Icon(
 Icons.Default.FitnessCenter,
 contentDescription = "Activity"
 )
 },
 label = { Text("Activity") },
 selected = currentRoute == "activity",
 onClick = {
 navController.navigate("activity") {
 popUpTo("dashboard")
 }
 }
 )
 NavigationBarItem(
 icon = { Icon(Icons.Default.Settings, contentDescription = "Settings") },
 label = { Text("Settings") },
 selected = currentRoute == "settings",
 onClick = {
 navController.navigate("settings") {
 popUpTo("dashboard")
 }
 }
 )
 }
 }
 ) { innerPadding ->
 NavHost(
 navController = navController,
 startDestination = "dashboard",
 modifier = Modifier.padding(innerPadding)
 ) {
 composable("dashboard") {
 SimpleDashboardScreen()
 }
 composable("health") {
 SimpleHealthScreen()
 }
 composable("aichat") {
 SimpleAIChatScreen()
 }
 composable("activity") {
 SimpleActivityScreen()
 }
 composable("vet") {
 SimpleVetScreen()
 }
 composable("settings") {
 SimpleSettingsScreen()
 }
 }
 }
}

