 .fillMaxWidth()
 .padding(16.dp),
 horizontalArrangement = Arrangement.spacedBy(8.dp),
 verticalAlignment = Alignment.CenterVertically
 ) {
 // Input field
 TextField(
 value = inputText,
 onValueChange = { if (it.length <= 500) onInputChange(it) },
 modifier = Modifier.weight(1f),
 placeholder = {
 Text(
 "Ask about your pet's health...",
 color = Color.Gray.copy(alpha = 0.7f)
 )
 },
 enabled = isEnabled,
 leadingIcon = {
 Text("", fontSize = 20.sp)
 },
 trailingIcon = {
 if (inputText.isNotEmpty()) {
 IconButton(
 onClick = { onInputChange("") }
 ) {
 Icon(
 Icons.Default.Clear,
 contentDescription = "Clear",
 modifier = Modifier.size(18.dp)
 )
 }
 }
 },
 shape = RoundedCornerShape(24.dp),
 colors = TextFieldDefaults.colors(
 focusedIndicatorColor = Color.Transparent,
 unfocusedIndicatorColor = Color.Transparent,
 disabledIndicatorColor = Color.Transparent
 ),
 keyboardOptions = KeyboardOptions(
 keyboardType = KeyboardType.Text,
 imeAction = ImeAction.Send
 ),
 keyboardActions = KeyboardActions(
 onSend = { if (inputText.isNotBlank()) onSendMessage() }
 ),
 maxLines = 3
 )

 // Voice input button
 IconButton(
 onClick = { /* TODO: Voice input */ },
 enabled = isEnabled
 ) {
 Icon(
 Icons.Default.Mic,
 contentDescription = "Voice Input",
 tint = if (isEnabled) Color(0xFF00BCD4) else Color.Gray
 )
 }

 // Send button
 Box(
 modifier = Modifier
 .size(48.dp)
 .clip(CircleShape)
 .background(
 if (!isLoading && inputText.isNotBlank() && isEnabled)
 Color(0xFF00BCD4)
 else
 Color.Gray
 )
 .clickable(
 enabled = !isLoading && inputText.isNotBlank() && isEnabled
 ) {
 onSendMessage()
 },
 contentAlignment = Alignment.Center
 ) {
 if (isLoading) {
 CircularProgressIndicator(
 modifier = Modifier.size(20.dp),
 color = Color.White,
 strokeWidth = 2.dp
 )
 } else {
 Icon(
 Icons.Default.Send,
 contentDescription = "Send",
 tint = Color.White,
 modifier = Modifier.size(20.dp)
 )
 }
 }
 }
 }
 }
}

