 }
 },
 text = {
 Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
 Text(
 text = "Add a custom GGUF model from HuggingFace or other sources:",
 style = MaterialTheme.typography.bodyMedium,
 color = Color.Gray
 )

 TextField(
