+```kotlin
+// Card with elevation
+Card(
+ modifier = Modifier.fillMaxWidth(),
+ colors = CardDefaults.cardColors(containerColor = Color(0xFFE3F2FD)),
+ elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
